struct string_buf;

class stringx
{
protected:
	char *chars;
	string_buf *my_buf;

public:
	stringx(const stringx &cp);
	stringx(const char *str, int len = -1);
	~stringx();
};

class HelpbarFE
{
private:
	enum {
		ARROW_H,
		ARROW_V,
		ARROW_BOTH,
		CROSS,
		TRIANGLE,
		CIRCLE,
		SQUARE,
		BTN_NUM
	};

	void ChangeBtn(int index, bool add, stringx text);

public:
	void AddArrowBoth(stringx text=stringx(""))	{ ChangeBtn(ARROW_BOTH, true, text);  ChangeBtn(ARROW_H, false, ""); ChangeBtn(ARROW_H, false, "");}
	void AddArrowV(stringx text=stringx(""))	{ ChangeBtn(ARROW_V, true, text); ChangeBtn(ARROW_BOTH, false, ""); }
	void RemoveX()								{ ChangeBtn(CROSS, false, ""); }
	void Reset();
	void Reformat();
};

class FEManager
{
	char padding[0x156A4];
public:
	HelpbarFE *helpbar;
};

struct FEMenuEntry
{
	int entry_num;
};

class FEMultiMenu
{
protected:
	char padding0[0x4C];
	FEMenuEntry *highlighted;
	char padding1[0xEC];
	FEManager *manager;
};

class ExtrasFrontEnd : public FEMultiMenu
{
public:
	enum {	ExtrasBeachesEntry,
			ExtrasSurfersEntry,
			ExtrasTrailersEntry,
			ExtrasHighScoreEntry,
			ExtrasScrapbookEntry,
			ExtrasCheatsEntry,
			ExtrasCreditsEntry,
			ExtrasWebsitesEntry,
			ExtrasLogbookEntry,
			ExtrasTHDemoEntry,
			ExtrasDemoEntryYes,
			ExtrasDemoEntryNo,
			ExtrasEndEntry };

private:
	void UpdateHelpbar();
};

void ExtrasFrontEnd::UpdateHelpbar()
{
	manager->helpbar->Reset();

	switch(highlighted->entry_num)
	{
	case ExtrasBeachesEntry:
	case ExtrasSurfersEntry:
	case ExtrasTrailersEntry:
		manager->helpbar->AddArrowBoth();
		break;
	case ExtrasCreditsEntry:
	case ExtrasCheatsEntry:
	case ExtrasScrapbookEntry:
	case ExtrasLogbookEntry:
	case ExtrasTHDemoEntry:
	case ExtrasHighScoreEntry:
		manager->helpbar->AddArrowV();
		break;
	case ExtrasWebsitesEntry:
		manager->helpbar->AddArrowV();
		manager->helpbar->RemoveX();
		break;
	}

	manager->helpbar->Reformat();
}
